// Pure renderers for persisted research, typed facts and rule provenance.
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=value=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:4}).format(value);
export function provenanceHTML(p){
 if(!p)return '<p>Происхождение правила не указано.</p>';
 return `<details class="rule-source"><summary>${escape(p.kind)} · источник и вес</summary><p>${escape(p.basis)}</p><p><b>Основание CF:</b> ${escape(p.cf_basis)}</p><p><a href="${escape(p.source_url)}" target="_blank" rel="noopener">${escape(p.source_label)}</a></p>${p.references.map(s=>`<p><a href="${escape(s.url)}" target="_blank" rel="noopener">${escape(s.title)}</a><br><small>${escape(s.scope)}</small></p>`).join('')}${!p.references.length?'<p><small>Отдельный внешний технический источник для этой эвристики не заявлен.</small></p>':''}</details>`;
}
export function propertyHTML(facts){
 if(!facts.length)return '';
 return `<section class="typed-properties"><h2>Числовые атрибуты</h2><p>Это отдельные записи «материал → атрибут → значение → единица → источник». Значения взяты из учебного каталога; паспорт и условия измерения отсутствуют.</p><div class="table-wrap"><table class="grid"><thead><tr><th>Изделие</th><th>Атрибут</th><th>Значение</th><th>Единица</th><th>Источник и условия</th></tr></thead><tbody>${facts.map(p=>`<tr><td>${escape(p.product)}</td><td>${escape(p.label)}</td><td>${number(p.value)}</td><td>${escape(p.unit)}</td><td><a href="${escape(p.source_url)}" target="_blank" rel="noopener">${escape(p.source_kind)}</a><br><small>${escape(p.conditions)}</small></td></tr>`).join('')}</tbody></table></div></section>`;
}
export function researchHTML(r){
 if(!r)return '<p>Сохранённое исследование не выполнено.</p>';
 const pct=v=>number(v*100)+' %';
 const quality=Object.values(r.quality).flatMap(c=>Object.entries(c.by_kind).map(([k,v])=>`<tr><td>${escape(c.label)}</td><td>${escape(k)} · ${v.queries.length}</td><td>${pct(v['P@1'])}</td><td>${number(v.MRR)}</td><td>${pct(v['R@5'])}</td></tr>`)).join('');
 const growth=r.scaling.stages.map(s=>`<tr><td>${s.articles}</td><td>${number(s.build.median_ms)}</td><td>${number(s.search.reduce((a,q)=>a+q.median_ms,0)/s.search.length)}</td><td>${number(s.inference.median_ms)}</td></tr>`).join('');
 return `<section class="research-results"><h2>Сохранённое исследование</h2><p>Снимок от ${escape(r.generated_at)}. Корпус: ${r.counts.articles} статей, ${r.counts.concepts} понятий, ${r.counts.rules} правил.</p><h3>Качество поиска</h3><p>P@1 — доля запросов с релевантным первым ответом; MRR — средняя обратная позиция первого релевантного ответа; R@5 — полнота первой пятёрки относительно разметки.</p><div class="table-wrap"><table class="grid"><thead><tr><th>Вариант</th><th>Запросы</th><th>P@1</th><th>MRR</th><th>R@5</th></tr></thead><tbody>${quality}</tbody></table></div><p>Разметка авторская и ограниченная. Отключение механизма не обязано ухудшать каждую метрику на таком небольшом наборе.</p><h3>Рост корпуса</h3><p>${escape(r.scaling.method)}</p><div class="table-wrap"><table class="grid"><thead><tr><th>Статей</th><th>Индекс, медиана мс</th><th>Поиск, среднее медиан мс</th><th>Вывод, медиана мс</th></tr></thead><tbody>${growth}</tbody></table></div><h3>Контроль рекомендаций</h3><p><b>${r.expert.passed} / ${r.expert.total}</b> сценариев прошли проверку. ${escape(r.expert.method)}</p><details><summary>Показать входы и ожидаемые результаты</summary><div class="table-wrap"><table class="grid"><thead><tr><th>Сценарий</th><th>Вход</th><th>Ожидается первым</th><th>Получено первым</th><th>Итог</th></tr></thead><tbody>${r.expert.cases.map(c=>`<tr><td>${escape(c.id)}</td><td>${escape(JSON.stringify(c.answers))}</td><td>${escape(c.top.join(' / ')||'Воздержаться')}</td><td>${escape(c.actual[0]||'Нет рекомендации')}</td><td>${c.passed?'Пройдено':'Расхождение'}</td></tr>`).join('')}</tbody></table></div></details><h3>Аудит графа</h3><p>${r.graph.nodes} узлов и ${r.graph.relations} связей. Изолированных узлов: ${r.graph.isolates.length}; компонент без направления: ${r.graph.weak_components.length}. Среднее исходящих связей: ${number(r.graph.mean_out_degree)}; суммарная степень: ${number(r.graph.mean_total_degree)}.</p><p>${escape(r.graph.note)}</p><details><summary>Ограничения и воспроизведение</summary><ul>${r.limitations.map(s=>`<li>${escape(s)}</li>`).join('')}</ul><p>Повторить: <code>python docs/research.py</code>. Среда: Python ${escape(r.environment.python)}, ${escape(r.environment.os)} ${escape(r.environment.architecture)}.</p><p>SHA-256: <code class="hash">${escape(r.dataset_sha256)}</code></p></details></section>`;
}
